import numpy as np
from scipy.optimize import least_squares

def residuals(x):
    return np.array([10 * (x[1] - x[0]**2), 1 - x[0]])

result = least_squares(residuals, x0=np.array([-1.2, 1.0]))
print(result.x)

import numpy as np
from scipy.optimize import root

def residual(x):
    return np.array([x[0]**2 - 2.0])

sol = root(residual, x0=np.array([1.0]))
print(sol.x[0], sol.success)
